"""Manual review serializer for the remaining existing-historian life checks."""
import json
from pathlib import Path
D=Path(__file__).parent
old={p['person_id']:p for p in json.loads(Path('data/people-wikidata.json').read_text())['people']}
rows={}
def add(pid,status,url,title,locator,support,identity,year=None,date=None,limits='',birth=None):
 prev=old.get(pid,{});life=prev.get('life')or{};qid=(prev.get('wikidata')or{}).get('qid')
 r=dict(person_id=pid,status=status,death_year=year,death_date=date,death_precision='day' if date else 'year' if year else None,checked_on='2026-10-25',identity_rationale=identity,sources=[dict(url=url,title=title,locator=locator,support=support,checked_on='2026-10-25',check_scope='Web-returned page text/search extract inspected for the stated biographical scope; underlying books and archive collections not read.')],previous_death_data=dict(sheet='data/people-wikidata.json',record_present=bool(prev),qid=qid,death=life.get('death'),death_precision=life.get('death_precision'),retrieved=life.get('retrieved'),source=life.get('source')),confidence='high' if status=='deceased' else 'moderate' if status=='living' else 'limited',limits=limits or ('Positive current institutional/author biography supports living status as checked; directory maintenance and date of last contact are not independently guaranteed. No absent P570 is treated as proof of life.' if status=='living' else 'Death year supported; no work, career or influence interval inferred from lifespan.'))
 if birth:r['birth_year']=birth
 if life.get('death') and not date and pid not in ['fernand_braudel','e_a_wrigley']:
  r['retained_prior_precise_death']=dict(date=life['death'],precision=life.get('death_precision'),source_url='https://www.wikidata.org/wiki/'+qid+'#P570',previous_checked_on=life.get('retrieved'),scope='Prior date-sheet statement retained as provenance; current source corroborates death year, not necessarily day.')
 rows[pid]=r

def extra(pid,url,title,locator,support):
 rows[pid]['sources'].append(dict(url=url,title=title,locator=locator,support=support,checked_on='2026-10-25',check_scope='Web-returned biographical text inspected for stated support only.'))
def finish(part):
 q=json.loads((D/f'queue-{part}.json').read_text())['people'];assert set(rows)=={p['person_id'] for p in q},set(rows)^{p['person_id'] for p in q}
 out=dict(schema_version='0.1',part=part,checked_on='2026-10-25',scope='34 assigned existing standalone historians; life metadata only.',method='Prior date sheet used as lead, identities matched by career/works, current institutional/authority/family evidence inspected. Ambiguous days and stale evidence explicitly qualified; missing P570 does not establish life.',search_scope=dict(date='2026-10-25',living_queries='Name, institutional affiliation,2026 and targeted obituary/death queries; source recency limits retained in individual records.',access_limit='Returned page text and indexed extracts, not full books or primary civil registers.'),counts={s:sum(x['status']==s for x in rows.values()) for s in ('deceased','living','unresolved')},people=[dict(label=p['label'],**rows[p['person_id']]) for p in q]);(D/f'results-{part}.json').write_text(json.dumps(out,ensure_ascii=False,indent=2)+'\n');print(part,out['counts']);rows.clear()
